CREATE TABLE schema_migrations (version VARCHAR(40) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
ALTER TABLE users ADD email VARCHAR(190) NULL, ADD registration_status ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Approved', ADD must_change_password TINYINT NOT NULL DEFAULT 0, ADD auth_version INT NOT NULL DEFAULT 1, ADD last_seen_at DATETIME NULL;
ALTER TABLE subjects ADD is_active TINYINT NOT NULL DEFAULT 1, ADD is_academic TINYINT NOT NULL DEFAULT 1;
CREATE TABLE courses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL UNIQUE, is_active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE school_years (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE, starts_on DATE NOT NULL, ends_on DATE NOT NULL, is_active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE terms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_year_id BIGINT UNSIGNED NOT NULL, name VARCHAR(40) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, submission_deadline DATE NOT NULL, inc_deadline DATE NOT NULL, is_active TINYINT NOT NULL DEFAULT 1, UNIQUE KEY uq_term (school_year_id,name), FOREIGN KEY (school_year_id) REFERENCES school_years(id)) ENGINE=InnoDB;
CREATE TABLE sections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, course_id BIGINT UNSIGNED NOT NULL, name VARCHAR(60) NOT NULL UNIQUE, year_level TINYINT NOT NULL, is_active TINYINT NOT NULL DEFAULT 1, FOREIGN KEY (course_id) REFERENCES courses(id)) ENGINE=InnoDB;
CREATE TABLE grading_policies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, midterm_weight DECIMAL(5,2) NOT NULL, rounding ENUM('floor','nearest') NOT NULL DEFAULT 'floor', repeat_rule ENUM('all','latest','best') NOT NULL DEFAULT 'all', include_nonacademic TINYINT NOT NULL DEFAULT 0, is_approved TINYINT NOT NULL DEFAULT 0, notes VARCHAR(1000) NOT NULL DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE offerings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, subject_id BIGINT UNSIGNED NOT NULL, term_id BIGINT UNSIGNED NULL, section_id BIGINT UNSIGNED NULL, faculty_id BIGINT UNSIGNED NULL, policy_id BIGINT UNSIGNED NULL, is_active TINYINT NOT NULL DEFAULT 1, needs_review TINYINT NOT NULL DEFAULT 0, legacy_term VARCHAR(40) NULL, UNIQUE KEY uq_offering (subject_id,term_id,section_id), FOREIGN KEY (subject_id) REFERENCES subjects(id), FOREIGN KEY (term_id) REFERENCES terms(id), FOREIGN KEY (section_id) REFERENCES sections(id), FOREIGN KEY (faculty_id) REFERENCES users(id), FOREIGN KEY (policy_id) REFERENCES grading_policies(id)) ENGINE=InnoDB;
ALTER TABLE students ADD course_id BIGINT UNSIGNED NULL, ADD section_id BIGINT UNSIGNED NULL, ADD honorable_dismissal_on DATE NULL, ADD FOREIGN KEY (course_id) REFERENCES courses(id), ADD FOREIGN KEY (section_id) REFERENCES sections(id);
CREATE TABLE enrollments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, offering_id BIGINT UNSIGNED NOT NULL, status ENUM('Enrolled','Completed','Withdrawn') NOT NULL DEFAULT 'Enrolled', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_enrollment (student_id,offering_id), FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (offering_id) REFERENCES offerings(id)) ENGINE=InnoDB;
ALTER TABLE grades DROP INDEX uq_grade_student_subject_term, MODIFY midterm DECIMAL(5,2) NULL, MODIFY final DECIMAL(5,2) NULL, MODIFY average DECIMAL(5,2) NULL, MODIFY gpa DECIMAL(3,2) NULL, MODIFY remarks ENUM('Passed','Failed','INC') NOT NULL, ADD offering_id BIGINT UNSIGNED NULL, ADD policy_id BIGINT UNSIGNED NULL, ADD units_snapshot DECIMAL(5,2) NULL, ADD academic_snapshot TINYINT NOT NULL DEFAULT 1, ADD workflow ENUM('Draft','Submitted','Approved','Published') NOT NULL DEFAULT 'Draft', ADD revision INT NOT NULL DEFAULT 1, ADD migration_review TINYINT NOT NULL DEFAULT 1, ADD inc_reason VARCHAR(1000) NULL, ADD inc_issued_on DATE NULL, ADD inc_deadline DATE NULL, ADD completion_reference VARCHAR(190) NULL, ADD completion_status ENUM('None','Pending','Completed','Expired') NOT NULL DEFAULT 'None', ADD submitted_at DATETIME NULL, ADD published_at DATETIME NULL, ADD correction_open TINYINT NOT NULL DEFAULT 0, ADD UNIQUE KEY uq_grade_offering (student_id,offering_id), ADD FOREIGN KEY (offering_id) REFERENCES offerings(id), ADD FOREIGN KEY (policy_id) REFERENCES grading_policies(id);
CREATE TABLE grade_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, grade_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NULL, action VARCHAR(40) NOT NULL, reason VARCHAR(1000) NOT NULL, before_data LONGTEXT NULL, after_data LONGTEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_history_grade (grade_id), FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
ALTER TABLE activity_logs ADD action VARCHAR(50) NOT NULL DEFAULT 'legacy', ADD entity VARCHAR(40) NULL, ADD record_id BIGINT UNSIGNED NULL, ADD before_data LONGTEXT NULL, ADD after_data LONGTEXT NULL, ADD offering_id BIGINT UNSIGNED NULL, ADD KEY idx_audit_action (action,created_at), ADD KEY idx_audit_offering (offering_id);
CREATE TABLE interventions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id BIGINT UNSIGNED NOT NULL, offering_id BIGINT UNSIGNED NOT NULL, adviser_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(1000) NOT NULL, follow_up_on DATE NOT NULL, notes TEXT NOT NULL, status ENUM('Open','In Progress','Resolved') NOT NULL DEFAULT 'Open', is_active TINYINT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (offering_id) REFERENCES offerings(id), FOREIGN KEY (adviser_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, offering_id BIGINT UNSIGNED NULL, message VARCHAR(500) NOT NULL, is_read TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE settings (setting_key VARCHAR(60) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB;
INSERT INTO settings VALUES ('school_name','Isabela State University'),('campus','Campus name - configure before issuing reports'),('report_header','Student Grade and Performance Analysis'),('registration_open','1'),('session_timeout','1800'),('session_epoch','1'),('active_term_id','0'),('gwa_policy_id','1'),('notifications_enabled','1'),('backup_retention_days','30'),('backup_schedule','manual'),('logo_path','assets/logo.svg');
INSERT INTO grading_policies(name,midterm_weight,rounding,notes) VALUES ('ISU scale / application default v1',50,'floor','ISU Section 18 conversion table. Equal weights and floor-to-integer conversion are application defaults pending institutional approval. INC excluded; all numeric attempts included; nonacademic excluded.');
INSERT INTO courses(code,name) SELECT CONCAT('LEGACY-', MIN(id)),course FROM students GROUP BY course;
UPDATE students s JOIN courses c ON c.name=s.course SET s.course_id=c.id;
INSERT INTO offerings(subject_id,needs_review,legacy_term) SELECT DISTINCT subject_id,1,academic_term FROM grades;
UPDATE grades g JOIN offerings o ON o.subject_id=g.subject_id AND o.legacy_term=g.academic_term SET g.offering_id=o.id;
INSERT INTO enrollments(student_id,offering_id) SELECT DISTINCT student_id,offering_id FROM grades;
INSERT INTO schema_migrations(version) VALUES ('002_academic_workflows');
